.editorial-theme{--ea-ink:#171512;--ea-paper:#f7f4ee;--ea-cream:#f3d8ae;--ea-accent:#a87b4e;--ea-line:rgba(23,21,18,.18);color:var(--ea-ink);background:var(--ea-paper);font-family:Arial,Helvetica,sans-serif;line-height:1.45}.editorial-theme *{box-sizing:border-box}.editorial-theme a{color:inherit;text-decoration:none}.editorial-theme h1,.editorial-theme h2,.editorial-theme h3,.editorial-theme p,.editorial-theme blockquote{margin:0}.editorial-theme h1,.editorial-theme h2,.editorial-theme .ea-featured-story h3,.editorial-theme .ea-testimonial p{font-family:Georgia,"Times New Roman",serif;font-weight:400;line-height:.94}.editorial-theme em{color:var(--ea-accent);font-style:normal}.editorial-theme .ea-icon{display:inline-block;flex:0 0 auto;filter:none;object-fit:contain;vertical-align:middle}.editorial-theme .ea-icon-light{filter:invert(1)}.editorial-theme .ea-menu,.editorial-theme .ea-event>a,.editorial-theme .ea-story-list small,.editorial-theme .ea-contact>a,.editorial-theme .ea-footer-bottom>a{align-items:center;display:inline-flex;gap:6px}
.ea-hero{min-height:760px;background:var(--ea-cream);padding:28px max(6vw,28px) 0;position:relative;overflow:hidden}.ea-nav{display:flex;align-items:center;justify-content:space-between;position:relative;z-index:5}.ea-mark{align-items:center;background:var(--ea-ink);border-radius:50%;color:white;display:inline-flex;font-family:Georgia,serif;font-size:12px;height:34px;justify-content:center;letter-spacing:-.04em;width:34px}.ea-nav nav{display:flex;gap:30px;text-transform:uppercase;font-size:10px;letter-spacing:.13em}.ea-nav nav a,.ea-menu{border-bottom:1px solid transparent;padding:7px 0}.ea-nav nav a:hover,.ea-menu:hover{border-color:currentColor}.ea-menu{font-size:11px;font-weight:700}.ea-hero-grid{display:grid;grid-template-columns:minmax(200px,1fr) minmax(340px,520px) minmax(180px,.8fr);max-width:1440px;margin:30px auto 0;min-height:695px;position:relative}.ea-hero-copy{align-self:center;position:relative;z-index:2}.ea-kicker{font-size:10px;font-weight:700;letter-spacing:.16em;text-transform:uppercase}.ea-hero h1{font-size:clamp(78px,9vw,142px);letter-spacing:-.075em;margin:30px 0 32px}.ea-hero h1 em{display:inline-block;margin-left:clamp(15px,4vw,70px)}.ea-intro{font-family:Georgia,serif;font-size:17px;line-height:1.5;max-width:320px}.ea-portrait-wrap{align-self:end;height:660px;position:relative}.ea-portrait-wrap img{bottom:0;height:100%;left:50%;object-fit:cover;object-position:center top;position:absolute;transform:translateX(-50%);width:100%;z-index:1}.ea-portrait-ring{border:1px solid rgba(23,21,18,.35);border-radius:50%;height:390px;left:50%;position:absolute;top:112px;transform:translateX(-50%);width:390px}.ea-experience{align-self:center;justify-self:end;position:relative;z-index:2;width:180px}.ea-experience>strong{font-family:Georgia,serif;font-size:62px;font-weight:400;line-height:1}.ea-experience sup{font:700 16px Arial}.ea-experience>span{display:block;font-size:10px;letter-spacing:.13em;margin:2px 0 55px;text-transform:uppercase}.ea-experience ul{border-top:1px solid var(--ea-ink);list-style:none;margin:0;padding:18px 0 0}.ea-experience li{font-size:11px;font-weight:700;margin:8px 0;text-transform:uppercase}
.ea-quote-band{align-items:center;background:#fff;border-bottom:1px solid var(--ea-line);display:grid;grid-template-columns:1fr 2fr 1fr;min-height:220px;padding:45px max(7vw,30px)}.ea-play{align-items:center;display:flex;gap:15px}.ea-play>span{align-items:center;border:1px solid var(--ea-ink);border-radius:50%;display:flex;height:54px;justify-content:center;width:54px}.ea-play small,.ea-laurel small{font-size:9px;letter-spacing:.12em;text-transform:uppercase}.ea-quote-band blockquote{font-family:Georgia,serif;font-size:clamp(22px,2.4vw,38px);font-style:italic;text-align:center}.ea-laurel{align-items:center;display:flex;gap:12px;justify-content:flex-end;text-align:center}.ea-laurel>span{font-size:25px;color:var(--ea-accent)}
.ea-section{margin:auto;max-width:1440px;padding:110px max(7vw,30px)}.ea-section-heading{align-items:end;display:grid;grid-template-columns:1fr 2fr;margin-bottom:65px}.ea-section-heading>p{font-size:11px;letter-spacing:.11em;max-width:230px;text-transform:uppercase}.ea-section-heading h2{font-size:clamp(48px,6vw,88px);letter-spacing:-.055em}.ea-event{align-items:center;border-top:1px solid var(--ea-line);display:grid;gap:28px;grid-template-columns:135px 1fr 120px 70px;padding:28px 0}.ea-event:last-child{border-bottom:1px solid var(--ea-line)}.ea-event time,.ea-event>span,.ea-event>a{font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase}.ea-event h3{font-family:Georgia,serif;font-size:27px;font-weight:400}.ea-event p{color:#6c6860;font-size:11px;margin-top:7px}.ea-event>a{text-align:right}
.ea-insights{background:#fff;max-width:none}.ea-insights>*{max-width:1240px;margin-left:auto;margin-right:auto}.ea-insights-heading{grid-template-columns:1.35fr .65fr}.ea-insights-heading>p{align-self:center;font-size:13px;letter-spacing:0;line-height:1.6;text-transform:none}.ea-insight-grid{display:grid;gap:50px;grid-template-columns:1.35fr .65fr}.ea-featured-story{display:block;position:relative}.ea-featured-story img{aspect-ratio:4/3;display:block;filter:saturate(.65);height:auto;object-fit:cover;width:100%}.ea-featured-story>span{background:var(--ea-cream);display:inline-block;font-size:9px;font-weight:700;letter-spacing:.1em;margin-top:24px;padding:8px 10px}.ea-featured-story h3{font-size:clamp(31px,4vw,58px);margin-top:18px;max-width:720px}.ea-story-list>a{border-top:1px solid var(--ea-line);display:block;padding:29px 0}.ea-story-list>a:last-child{border-bottom:1px solid var(--ea-line)}.ea-story-list span,.ea-story-list small{font-size:9px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.ea-story-list h3{font-family:Georgia,serif;font-size:25px;font-weight:400;line-height:1.15;margin:15px 0 28px}.ea-story-list .ea-all-notes{align-items:center;background:var(--ea-ink);border:0;color:white;display:flex;justify-content:space-between;margin-top:28px;padding:19px 22px}
.ea-testimonial{height:min(70vw,760px);overflow:hidden;position:relative}.ea-testimonial>img{filter:saturate(.55);height:100%;object-fit:cover;width:100%}.ea-testimonial blockquote{background:var(--ea-cream);bottom:12%;max-width:480px;padding:44px;position:absolute;right:8%}.ea-testimonial blockquote>span,.ea-testimonial cite{font-size:9px;font-style:normal;font-weight:700;letter-spacing:.1em;text-transform:uppercase}.ea-testimonial p{font-size:clamp(29px,3.5vw,52px);margin:22px 0 30px}
.ea-about{text-align:left}.ea-about>.ea-kicker{margin-bottom:35px}.ea-about h2{font-size:clamp(49px,6.7vw,100px);max-width:1220px}.ea-about-meta{align-items:center;border-bottom:1px solid var(--ea-line);display:flex;justify-content:space-between;margin-top:60px;padding-bottom:55px}.ea-about-meta>div:first-child{align-items:center;display:flex;gap:32px}.ea-signature{font-family:"Brush Script MT",cursive;font-size:31px}.ea-about-meta p{font-size:10px;letter-spacing:.08em;text-transform:uppercase}.ea-socials{display:flex;gap:10px}.ea-socials a{align-items:center;border:1px solid var(--ea-ink);border-radius:50%;display:flex;font-size:10px;font-weight:700;height:38px;justify-content:center;width:38px}.ea-trust{background:#fff;border-bottom:1px solid var(--ea-line);border-top:1px solid var(--ea-line);padding:36px max(7vw,30px);text-align:center}.ea-trust>span{display:block;font-size:8px;letter-spacing:.14em;margin-bottom:28px;text-transform:uppercase}.ea-trust>div{display:flex;justify-content:space-around;opacity:.4}.ea-trust b{font-family:Georgia,serif;font-size:17px}
.ea-background .ea-section-heading{grid-template-columns:1fr 1fr}.ea-background-grid{display:grid;gap:70px;grid-template-columns:1.2fr .8fr}.ea-background-grid>div>h3{border-bottom:1px solid var(--ea-ink);font-size:11px;letter-spacing:.1em;padding-bottom:14px;text-transform:uppercase}.ea-education article{align-items:center;border-bottom:1px solid var(--ea-line);display:grid;gap:25px;grid-template-columns:110px 1fr 40px;padding:22px 0}.ea-education time,.ea-education p{font-size:10px}.ea-education h4{font-family:Georgia,serif;font-size:18px;font-weight:400;margin:0 0 5px}.ea-education article>span{color:var(--ea-line);font-family:Georgia,serif;font-size:34px}.ea-skills article{align-items:center;background:#fff;display:grid;grid-template-columns:110px 1fr auto;margin-top:14px;padding:26px}.ea-skills article:nth-child(2){background:var(--ea-cream)}.ea-skills strong{font-family:Georgia,serif;font-size:38px;font-weight:400}.ea-skills span{font-size:12px;font-weight:700}.ea-skills small{font-size:9px}.ea-stats{border-top:1px solid var(--ea-line);display:grid;grid-template-columns:repeat(3,1fr);margin-top:90px;padding-top:50px;text-align:center}.ea-stats strong{display:block;font-family:Georgia,serif;font-size:65px;font-weight:400}.ea-stats span{font-size:9px;letter-spacing:.12em;text-transform:uppercase}
.ea-footer{background:var(--ea-ink);color:white;display:grid;gap:60px;grid-template-columns:1.3fr .7fr;padding:90px max(7vw,30px) 30px}.ea-mark-light{background:white;color:var(--ea-ink)}.ea-footer>div>p{font-size:11px;letter-spacing:.1em;margin:35px 0 12px;text-transform:uppercase}.ea-footer h2{font-size:clamp(45px,6vw,83px)}.ea-footer h2 em{color:var(--ea-cream)}.ea-contact{align-self:end;border-top:1px solid rgba(255,255,255,.3);padding-top:25px}.ea-contact>span{font-size:9px;letter-spacing:.12em;text-transform:uppercase}.ea-contact>a{border-bottom:1px solid white;display:flex;font-family:Georgia,serif;font-size:20px;justify-content:space-between;margin-top:22px;padding-bottom:12px}.ea-contact p{color:#aaa!important;line-height:1.8!important}.ea-footer-bottom{border-top:1px solid rgba(255,255,255,.15);display:flex;grid-column:1/-1;justify-content:space-between;padding-top:25px}.ea-footer-bottom span,.ea-footer-bottom a{font-size:9px;letter-spacing:.08em;text-transform:uppercase}
@media(max-width:900px){.ea-hero{min-height:980px}.ea-nav nav{display:none}.ea-hero-grid{grid-template-columns:1fr 1fr;min-height:900px}.ea-hero-copy{align-self:start;padding-top:80px}.ea-portrait-wrap{grid-column:1/-1;grid-row:2;height:580px;margin:auto;width:min(520px,90vw)}.ea-experience{align-self:start;padding-top:100px}.ea-quote-band{grid-template-columns:1fr}.ea-play,.ea-laurel{display:none}.ea-section-heading,.ea-insights-heading{gap:25px;grid-template-columns:1fr}.ea-insight-grid,.ea-background-grid{grid-template-columns:1fr}.ea-testimonial blockquote{bottom:5%;right:5%}.ea-footer{grid-template-columns:1fr}.ea-contact{margin-top:30px}}
@media(max-width:620px){.ea-hero{min-height:900px;padding-left:20px;padding-right:20px}.ea-hero-grid{display:block}.ea-hero-copy{padding-top:60px}.ea-hero h1{font-size:76px;margin:20px 0}.ea-intro{max-width:270px}.ea-portrait-wrap{height:470px;margin-top:15px;width:100%}.ea-experience{bottom:35px;padding:0;position:absolute;right:0;width:140px}.ea-experience>strong{font-size:42px}.ea-experience>span{margin-bottom:16px}.ea-experience ul{background:rgba(243,216,174,.84);padding:10px}.ea-quote-band{min-height:180px;padding:30px 20px}.ea-section{padding:75px 20px}.ea-section-heading{margin-bottom:40px}.ea-section-heading h2{font-size:49px}.ea-event{gap:12px;grid-template-columns:80px 1fr}.ea-event>span,.ea-event>a{display:none}.ea-event h3{font-size:20px}.ea-insights{padding-left:20px;padding-right:20px}.ea-testimonial{height:650px}.ea-testimonial blockquote{left:20px;max-width:none;padding:28px;right:20px}.ea-about h2{font-size:45px}.ea-about-meta,.ea-about-meta>div:first-child{align-items:flex-start;flex-direction:column}.ea-socials{margin-top:25px}.ea-trust>div{flex-wrap:wrap;gap:25px}.ea-background .ea-section-heading{grid-template-columns:1fr}.ea-education article{grid-template-columns:70px 1fr}.ea-education article>span{display:none}.ea-skills article{grid-template-columns:85px 1fr}.ea-skills small{display:none}.ea-stats{gap:30px;grid-template-columns:1fr}.ea-footer{padding:70px 20px 25px}.ea-footer h2{font-size:46px}.ea-footer-bottom{gap:20px}}

const icons = {
  "arrow-right": "/icons/solar-linear/arrow-right.svg",
  "arrow-to-top-right": "/icons/solar-linear/arrow-to-top-right.svg",
  "arrow-up": "/icons/solar-linear/arrow-up.svg",
  "global": "/icons/solar-linear/global.svg",
  "letter": "/icons/solar-linear/letter.svg",
  "medal-star": "/icons/solar-linear/medal-star.svg",
  "play-circle": "/icons/solar-linear/play-circle.svg",
  "share-circle": "/icons/solar-linear/share-circle.svg",
} as const;

export type ThemeIconName = keyof typeof icons;

export default function ThemeIcon({ name, size = 18, tone = "dark" }: { name: ThemeIconName; size?: number; tone?: "dark" | "light" }) {
  return <img className={`ea-icon${tone === "light" ? " ea-icon-light" : ""}`} src={icons[name]} width={size} height={size} alt="" aria-hidden="true" />;
}
